    "zt-lab.vlan.p": "Chaque zone est isolée — aucune communication inter-VLAN sans règle ACL explicite sur le firewall.",
    "zt-lab.vlan.th.id": "VLAN", "zt-lab.vlan.th.nom": "Nom", "zt-lab.vlan.th.role": "Rôle", "zt-lab.vlan.th.acces": "Accès inter-VLAN",
    "zt-lab.vlan.r1.nom": "Users",  "zt-lab.vlan.r1.role": "Postes utilisateurs",      "zt-lab.vlan.r1.acces": "Internet uniquement",
