    /* === VEILLE === */
    "veille.title": "[=== VEILLE TECHNOLOGIQUE ===]",
    "veille.theme": "Thème : <strong>Zero Trust Security Model</strong> (<em>Zero Trust Architecture</em>).",
    "veille.tab.concepts": "Concepts",
    "veille.tab.architecture": "Architecture",
    "veille.tab.usecases": "Cas d'usage",
    "veille.tab.analysis": "Analyse personnelle",
    "zt.concepts.h2": "Qu'est‑ce que le Zero Trust ?",
    "zt.concepts.p": "Le <strong>Zero Trust Security Model</strong> repose sur un principe fondamental : <strong>ne jamais faire confiance par défaut</strong>. Chaque accès est vérifié en continu, même à l'intérieur du réseau.",
    "zt.principles.h2": "Principes fondamentaux",
    "zt.principles.ul": "<li><strong>Vérification systématique</strong> — authentification de chaque requête.</li><li><strong>Moindre privilège</strong> — accès strictement nécessaire.</li><li><strong>Micro‑segmentation</strong> — isolation des ressources.</li><li><strong>Contrôle continu</strong> — évaluation permanente du contexte.</li><li><strong>Supposition de compromission</strong> — l'attaque peut venir de partout.</li>",
    "zt.compare.h2": "Avant / Après Zero Trust",
    "zt.compare.th1": "Modèle traditionnel",
    "zt.compare.th2": "Modèle Zero Trust",
    "zt.compare.r1c1": "Confiance implicite", "zt.compare.r1c2": "Confiance vérifiée",
    "zt.compare.r2c1": "Périmètre réseau",   "zt.compare.r2c2": "Identité &amp; contexte",
    "zt.compare.r3c1": "Accès large",          "zt.compare.r3c2": "Accès minimal",
    "zt.compare.r4c1": "Détection tardive",    "zt.compare.r4c2": "Surveillance continue",
    "zt.arch.simple.h2": "Schéma Zero Trust (vue simplifiée)",
    "zt.arch.advanced.h2": "Schéma Zero Trust (avancé)",
    "zt.usecase.google.h2": "Étude de cas : Google BeyondCorp",
    "zt.usecase.google.p": "Google a supprimé la notion de réseau interne de confiance. Chaque accès passe par une vérification d'identité et de contexte.",
    "zt.usecase.enterprise.h2": "Cas d'usage en entreprise",
    "zt.usecase.enterprise.ul": "<li>Remplacement du VPN par <strong>ZTNA</strong></li><li>Segmentation des serveurs</li><li>MFA obligatoire</li><li>Contrôle de conformité des postes</li><li>Analyse comportementale en temps réel</li>",
    "zt.usecase.ransomware.h2": "Exemple : attaque ransomware",
    "zt.usecase.ransomware.p1": "<strong>Sans Zero Trust :</strong> propagation rapide.",
    "zt.usecase.ransomware.p2": "<strong>Avec Zero Trust :</strong>",
    "zt.usecase.ransomware.ul": "<li>MFA bloque l'accès initial</li><li>Micro‑segmentation limite la propagation</li><li>EDR/XDR détecte l'anomalie</li><li>Accès compromis automatiquement coupé</li>",
    "zt.analysis.h2": "Analyse personnelle",
    "zt.analysis.p1": "Le Zero Trust représente pour moi une évolution logique de la cybersécurité moderne dans des environnements distribués.",
    "zt.analysis.p2": "Il combine IAM, MFA, supervision et architecture réseau, ce qui correspond à ma manière de travailler et à mon projet professionnel.",
    "zt.conclusion.h2": "Conclusion",
    "zt.conclusion.p": "Le Zero Trust n'est pas un produit mais une stratégie globale indispensable pour renforcer la résilience face aux menaces actuelles.",
    "zt.faq.h2": "FAQ Zero Trust",
    "zt.faq.ul": "<li><strong>Zéro confiance ?</strong> → confiance vérifiée.</li><li><strong>Remplace le VPN ?</strong> → oui, via ZTNA.</li><li><strong>Déploiement long ?</strong> → progressif.</li><li><strong>Réservé aux grandes entreprises ?</strong> → non.</li>",
