    "zt.concepts.h2": "What is Zero Trust?",
    "zt.concepts.p": "The <strong>Zero Trust Security Model</strong> is based on a fundamental principle: <strong>never trust by default</strong>. Every access is continuously verified, even inside the network.",
    "zt.principles.h2": "Core principles",
    "zt.principles.ul": "<li><strong>Systematic verification</strong> — authentication of every request.</li><li><strong>Least privilege</strong> — strictly necessary access.</li><li><strong>Micro-segmentation</strong> — resource isolation.</li><li><strong>Continuous control</strong> — permanent context evaluation.</li><li><strong>Assume breach</strong> — attacks can come from anywhere.</li>",
    "zt.compare.h2": "Before / After Zero Trust",
    "zt.compare.th1": "Traditional model",
    "zt.compare.th2": "Zero Trust model",
    "zt.compare.r1c1": "Implicit trust",      "zt.compare.r1c2": "Verified trust",
    "zt.compare.r2c1": "Network perimeter",   "zt.compare.r2c2": "Identity &amp; context",
    "zt.compare.r3c1": "Broad access",         "zt.compare.r3c2": "Minimal access",
    "zt.compare.r4c1": "Late detection",       "zt.compare.r4c2": "Continuous monitoring",
    "zt.arch.simple.h2": "Zero Trust diagram (simplified view)",
    "zt.arch.advanced.h2": "Zero Trust diagram (advanced)",
    "zt.usecase.google.h2": "Case study: Google BeyondCorp",
    "zt.usecase.google.p": "Google eliminated the concept of a trusted internal network. Every access goes through identity and context verification.",
    "zt.usecase.enterprise.h2": "Enterprise use cases",
    "zt.usecase.enterprise.ul": "<li>Replacing VPN with <strong>ZTNA</strong></li><li>Server segmentation</li><li>Mandatory MFA</li><li>Device compliance checks</li><li>Real-time behavioral analysis</li>",
    "zt.usecase.ransomware.h2": "Example: ransomware attack",
    "zt.usecase.ransomware.p1": "<strong>Without Zero Trust:</strong> rapid propagation.",
    "zt.usecase.ransomware.p2": "<strong>With Zero Trust:</strong>",
    "zt.usecase.ransomware.ul": "<li>MFA blocks initial access</li><li>Micro-segmentation limits propagation</li><li>EDR/XDR detects the anomaly</li><li>Compromised access automatically cut</li>",
    "zt.analysis.h2": "Personal analysis",
    "zt.analysis.p1": "Zero Trust represents for me a logical evolution of modern cybersecurity in distributed environments.",
    "zt.analysis.p2": "It combines IAM, MFA, monitoring and network architecture, which aligns with my way of working and professional project.",
    "zt.conclusion.h2": "Conclusion",
    "zt.conclusion.p": "Zero Trust is not a product but a comprehensive strategy essential for strengthening resilience against current threats.",
    "zt.faq.h2": "Zero Trust FAQ",
    "zt.faq.ul": "<li><strong>Zero trust?</strong> → verified trust.</li><li><strong>Replaces VPN?</strong> → yes, via ZTNA.</li><li><strong>Long deployment?</strong> → progressive.</li><li><strong>For large enterprises only?</strong> → no.</li>",
